package org.eclipse.rdf4j.http.server.repository;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.nio.file.Path;

import org.eclipse.rdf4j.http.protocol.RepositoryDeletionDeniedException;
import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.TreeModel;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.RepositoryResult;
import org.eclipse.rdf4j.repository.config.RepositoryConfig;
import org.eclipse.rdf4j.repository.manager.LocalRepositoryManager;
import org.eclipse.rdf4j.repository.sail.config.SailRepositoryConfig;
import org.eclipse.rdf4j.sail.memory.config.MemoryStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class RepositoryConfigRepositoryDeletionTest {

	@TempDir
	Path directory;
	private LocalRepositoryManager manager;

	@BeforeEach
	void setUp() {
		manager = new LocalRepositoryManager(directory.toFile());
		manager.init();
		manager.addRepositoryConfig(config("edit", "original"));
		manager.addRepositoryConfig(config("delete", "original"));
	}

	@AfterEach
	void shutDown() {
		manager.shutDown();
	}

	@Test
	void unauthorizedAutocommitCannotDelete() {
		try (RepositoryConnection connection = new RepositoryConfigRepository(manager, false).getConnection()) {
			Resource context = context(connection, "delete");
			assertThatThrownBy(() -> connection.clear(context)).isInstanceOf(RepositoryDeletionDeniedException.class);
			assertThat(manager.hasRepositoryConfig("delete")).isTrue();
		}
	}

	@Test
	void mixedEditAndDeletionAreCheckedBeforeAnyEffects() {
		try (RepositoryConnection connection = new RepositoryConfigRepository(manager, false).getConnection()) {
			connection.begin();
			Resource editContext = context(connection, "edit");
			connection.clear(editContext);
			Model edited = new TreeModel();
			config("edit", "changed").export(edited, editContext);
			connection.add(edited);
			connection.clear(context(connection, "delete"));
			assertThatThrownBy(connection::commit).isInstanceOf(RepositoryDeletionDeniedException.class);
			assertThat(manager.getRepositoryConfig("edit").getTitle()).isEqualTo("original");
			assertThat(manager.hasRepositoryConfig("delete")).isTrue();
			connection.rollback();
		}
	}

	@Test
	void creationAndConfigurationEditDoNotRequireDeletionAuthorization() {
		try (RepositoryConnection connection = new RepositoryConfigRepository(manager, false).getConnection()) {
			connection.begin();
			Resource editContext = context(connection, "edit");
			connection.clear(editContext);
			Model model = new TreeModel();
			config("edit", "changed").export(model, editContext);
			config("created", "new").export(model);
			connection.add(model);
			connection.commit();
			assertThat(manager.getRepositoryConfig("edit").getTitle()).isEqualTo("changed");
			assertThat(manager.hasRepositoryConfig("created")).isTrue();
		}
	}

	@Test
	void authorizedDeletionUsesCapturedDecision() {
		try (RepositoryConnection connection = new RepositoryConfigRepository(manager, true).getConnection()) {
			connection.begin();
			connection.clear(context(connection, "delete"));
			connection.commit();
			assertThat(manager.hasRepositoryConfig("delete")).isFalse();
		}
	}

	private static RepositoryConfig config(String id, String title) {
		return new RepositoryConfig(id, title, new SailRepositoryConfig(new MemoryStoreConfig()));
	}

	private static Resource context(RepositoryConnection connection, String id) {
		try (RepositoryResult<Resource> contexts = connection.getContextIDs()) {
			while (contexts.hasNext()) {
				Resource context = contexts.next();
				if (context.stringValue().endsWith("#" + id)) {
					return context;
				}
			}
		}
		throw new AssertionError("Missing configuration context for " + id);
	}
}
